"use strict";
import { useMorphoVault } from "hooks/morpho";
import { useMemo } from "react";
import { useSearchParams } from "react-router-dom";
import { Flex, SpinningLoader, Text } from "ui/src";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { VaultContextProvider, useVaultContext } from "./ContextProvider";
import { EarnContextProvider, useEarnContext } from "../ContextProvider";
import BackButton from "../components/BackButton";
import ConfirmModal from "../components/ConfirmModal";
import ReviewModal from "../components/ReviewModal";
import ActionBar from "./components/ActionBar";
import ActivityTab from "./components/Activity/ActivityTab";
import DepositWithdraw from "./components/DepositWithdraw";
import Vault from "./components/Vault";
import OverviewTab from "./components/overview/OverviewTab";
import PerformaceTab from "./components/performace/PerformaceTab";
import RiskTab from "./components/risk/RiskTab";
import YourPosition from "./components/yourPosition/YourPosition";
const TOKEN_PRICES_USD = {
  USDC: 1,
  WETH: 3500,
  ETH: 3500
};
function getTokenPriceUsd(symbol) {
  return TOKEN_PRICES_USD[symbol.toUpperCase()] ?? 1;
}
function transformMorphoVaultToVaultData(morphoVault) {
  const totalAssetsNumber = Number(morphoVault.totalAssetsFormatted);
  const totalIdleNumber = Number(morphoVault.totalIdleFormatted);
  const tokenPriceUsd = getTokenPriceUsd(morphoVault.asset.symbol);
  const depositsUsd = totalAssetsNumber * tokenPriceUsd;
  const liquidityUsd = totalIdleNumber * tokenPriceUsd;
  return {
    id: morphoVault.address,
    address: morphoVault.address,
    name: morphoVault.name,
    symbol: morphoVault.symbol,
    token: {
      id: morphoVault.asset.address,
      address: morphoVault.asset.address,
      symbol: morphoVault.asset.symbol,
      name: morphoVault.asset.name,
      decimals: morphoVault.asset.decimals
    },
    deposits: totalAssetsNumber,
    depositsUsd,
    liquidity: totalIdleNumber,
    liquidityUsd,
    exposure: 0,
    apy: 0,
    sharePrice: Number(morphoVault.sharePriceFormatted),
    feePercent: morphoVault.feePercent,
    isVerified: true
  };
}
function EarnContent() {
  const { activeTab } = useVaultContext();
  const { transactionStep, selectedVault, closeTransaction } = useEarnContext();
  const [searchParams] = useSearchParams();
  const chainId = UniverseChainId.Mainnet;
  const vaultAddress = searchParams.get("address");
  const { data: morphoVault, isLoading, isError } = useMorphoVault(vaultAddress ?? void 0, chainId);
  const vault = useMemo(() => {
    if (!morphoVault) return null;
    return transformMorphoVaultToVaultData(morphoVault);
  }, [morphoVault]);
  if (isLoading) {
    return <Flex width={"100vw"} centered py="$spacing48">
        <SpinningLoader size={32} />
      </Flex>;
  }
  if (isError || !vault) {
    return <Flex width={"100vw"} centered py="$spacing48">
        <Text variant="body1" color="$neutral2">
          Vault not found
        </Text>
      </Flex>;
  }
  return <Flex width={"100vw"} px={"$spacing12"}>
      <Flex
    mt="$spacing24"
    mx={"auto"}
    width="100%"
    px="$spacing24"
    maxWidth={1980}
    pb={"$spacing40"}
    gap={"$spacing36"}
    $platform-web={{ display: "grid", gridTemplateColumns: "3fr 1fr" }}
    $xl={{ display: "block", px: "0" }}
    $xxxl={{ gridTemplateColumns: "2fr 1fr" }}
  >
        <Flex className="left" maxWidth={1200} width={"100%"}>
          <BackButton />
          <Vault vaultData={vault} />
          <ActionBar />
          {activeTab === "Your position" && <YourPosition />}
          {activeTab === "Performance" && <PerformaceTab />}
          {activeTab === "Overview" && <OverviewTab />}
          {activeTab === "Risk" && <RiskTab />}
          {activeTab === "Activity" && <ActivityTab />}
        </Flex>
        <Flex className="right" width={"100%"} row justifyContent="center" mt={"$spacing32"}>
          <DepositWithdraw vault={vault} />
        </Flex>
      </Flex>

      {
    /* Transaction Modals */
  }
      {transactionStep === "review" && selectedVault && <ReviewModal isOpen={true} onClose={closeTransaction} vault={selectedVault} />}
      {transactionStep === "confirm" && selectedVault && <ConfirmModal isOpen={true} onClose={closeTransaction} vault={selectedVault} />}
    </Flex>;
}
export default function Earn() {
  return <VaultContextProvider>
      <EarnContextProvider>
        <EarnContent />
      </EarnContextProvider>
    </VaultContextProvider>;
}
